CREATE OR REPLACE FUNCTION public.get_history_month(_tz text,_month date) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $fn$
WITH days AS (SELECT generate_series(date_trunc('month',_month)::date,(date_trunc('month',_month)+interval '1 month - 1 day')::date,interval '1 day')::date AS d), fs AS (SELECT (started_at AT TIME ZONE _tz)::date AS d,sum(actual_min) AS minutes FROM public.focus_sessions WHERE user_id=auth.uid() AND started_at>=date_trunc('month',_month)::timestamp AT TIME ZONE _tz AND started_at<(date_trunc('month',_month)+interval '1 month')::timestamp AT TIME ZONE _tz GROUP BY 1), ps AS (SELECT (at AT TIME ZONE _tz)::date AS d,count(*) AS primes FROM public.prime_sessions WHERE user_id=auth.uid() AND at>=date_trunc('month',_month)::timestamp AT TIME ZONE _tz AND at<(date_trunc('month',_month)+interval '1 month')::timestamp AT TIME ZONE _tz GROUP BY 1)
SELECT jsonb_agg(jsonb_build_object('day',days.d,'minutes',coalesce(fs.minutes,0),'primes',coalesce(ps.primes,0)) ORDER BY days.d) FROM days LEFT JOIN fs USING(d) LEFT JOIN ps USING(d) $fn$;
GRANT EXECUTE ON FUNCTION public.get_history_month(text,date) TO authenticated; REVOKE EXECUTE ON FUNCTION public.get_history_month(text,date) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.get_history_week(_from timestamptz,_to timestamptz,_type text DEFAULT 'all',_search text DEFAULT '',_offset int DEFAULT 0) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $fn$
WITH entries AS (
SELECT 'session' AS type,id,started_at AS at,to_jsonb(f)-'user_id' AS row FROM public.focus_sessions f WHERE user_id=auth.uid() AND started_at>=_from AND started_at<_to AND _type IN ('all','session') AND (_search='' OR intention ILIKE '%'||_search||'%' ESCAPE '\' OR done_note ILIKE '%'||_search||'%' ESCAPE '\')
UNION ALL SELECT 'prime',id,at,to_jsonb(p)-'user_id' FROM public.prime_sessions p WHERE user_id=auth.uid() AND at>=_from AND at<_to AND _type IN ('all','prime') AND (_search='' OR intention ILIKE '%'||_search||'%' ESCAPE '\')
UNION ALL SELECT 'rating',id,at,to_jsonb(r)-'user_id' FROM public.energy_ratings r WHERE user_id=auth.uid() AND at>=_from AND at<_to AND _type IN ('all','rating') AND (_search='' OR note ILIKE '%'||_search||'%' ESCAPE '\')
), page AS (SELECT * FROM entries ORDER BY at DESC,id LIMIT 500 OFFSET greatest(_offset,0))
SELECT jsonb_build_object('entries',coalesce((SELECT jsonb_agg((row||jsonb_build_object('type',type,'at',at,'interruptions',CASE WHEN type='session' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'source',i.source,'reason',i.reason,'custom_label',i.custom_label,'at',i.at) ORDER BY i.at) FROM public.interruptions i WHERE i.user_id=auth.uid() AND i.session_id=page.id),'[]'::jsonb) ELSE '[]'::jsonb END)) ORDER BY at DESC,id) FROM page),'[]'::jsonb),'more',(SELECT count(*) FROM entries)>greatest(_offset,0)+500)
$fn$;
GRANT EXECUTE ON FUNCTION public.get_history_week(timestamptz,timestamptz,text,text,int) TO authenticated; REVOKE EXECUTE ON FUNCTION public.get_history_week(timestamptz,timestamptz,text,text,int) FROM PUBLIC,anon;